// The Learn index (learn/index.json, generated by scripts/build_flashcards.py)
// and the orderings derived from it (pure functions, no DOM).

// Flatten the index into pages in wiki order, each knowing its topic.
export function indexLearn(data) {
  const topics = Array.isArray(data?.topics) ? data.topics : [];
  const pages = [];
  for (const topic of topics) {
    for (const page of topic.pages ?? []) pages.push({ ...page, topic: topic.slug, topicName: topic.name });
  }
  return {
    topics,
    pages,
    byKey: new Map(pages.map((page) => [`${page.topic}/${page.slug}`, page])),
    byPath: new Map(pages.map((page) => [page.path, page])),
  };
}

export function isLearned(store, page) {
  return store.page(page.path)?.learned === 1;
}

// The page after `page` in wiki order: the next page of its topic, then the
// first page of the following topic.
export function nextPage(learn, page) {
  const index = learn.pages.findIndex((entry) => entry.path === page.path);
  return index >= 0 ? learn.pages[index + 1] ?? null : null;
}

// The first page with questions that is not learned yet, in wiki order.
export function nextToLearn(learn, store) {
  return learn.pages.find((page) => page.questions.length && !isLearned(store, page)) ?? null;
}

// The reader route for a page, optionally at a section.
export function pageHash(page, anchor = null) {
  const encode = encodeURIComponent;
  return `#/learn/${encode(page.topic)}/${encode(page.slug)}` + (anchor ? `/${encode(anchor)}` : "");
}
